args.command:
node - /tau/in/list.txt <<'EOF'
import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'

const ids: number[] = []
for (const line of readFileSync(process.argv[2] ?? '', 'utf8').split('\n').filter(Boolean)) {
  const [text = '', tags = ''] = line.split('#')
  const tagged = tags.split(',').map(tag => tag.trim()).filter(Boolean).flatMap(tag => ['--tag', tag])
  ids.push(JSON.parse(execFileSync('notes', ['add', text.trim(), ...tagged], { encoding: 'utf8' })).id)
}
console.log(JSON.stringify(ids))
EOF
